def main():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    o = n + 1
    array = [i + 1 for i in range(n)]
    m = int(next(it))

    for _ in range(m):
        r = int(next(it))
        # Java loop: for (int l = r-1; l < o-1; l++) array[l] = r;
        # Python slice assignment: array[r-1 : o-1] = [r] * length
        start = r - 1
        end = o - 1
        if start < end:
            array[start:end] = [r] * (end - start)
        if r < o:
            o = r

    print(' '.join(map(str, array)))

if __name__ == "__main__":
    main()

